using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;
public static class FinalizeClothing {
 public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");const string prefab="Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2.prefab";var root=PrefabUtility.LoadPrefabContents(prefab);try{var binding=root.GetComponent<CharacterGarmentSurfaceBinding>();if(binding){binding.Release();UnityEngine.Object.DestroyImmediate(binding);}var all=root.GetComponentsInChildren<SkinnedMeshRenderer>(true);var cloth=all.Single(r=>r.name=="BAKED_Outfits_LOD0");var body=all.Single(r=>r.name=="BAKED_body_lod0_mesh");cloth.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/_Sandbox/Characters/Ethan_V2/Meshes/EthanV2_Outfit_BodyBound.asset");cloth.enabled=true;cloth.rootBone=root.transform;cloth.localBounds=new Bounds(new Vector3(0,1.1f,0),new Vector3(2.4f,2.4f,2.4f));body.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/_Sandbox/Characters/Ethan_V2/Meshes/EthanV2_Body_ShirtCoverage.asset");if(!body.sharedMesh||!cloth.sharedMesh)throw new Exception("Missing reviewed clothing assets");PrefabUtility.SaveAsPrefabAsset(root,prefab);AssetDatabase.SaveAssets();return new{shirtEnabled=cloth.enabled,clothingCullingRoot=cloth.rootBone.name,bounds=cloth.localBounds.ToString(),bodyTriangles=body.sharedMesh.triangles.Length/3,shirtTriangles=cloth.sharedMesh.triangles.Length/3,noRuntimeClothingDeformer=true};}finally{PrefabUtility.UnloadPrefabContents(root);}}
}
